import java.time.Duration;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class Solution {

    @FunctionalInterface
    public interface PriceService {
        double price(String sku) throws Exception;
    }

    @FunctionalInterface
    public interface InventoryService {
        int stock(String sku) throws Exception;
    }

    @FunctionalInterface
    public interface ShippingService {
        double shipping(String sku, int quantity) throws Exception;
    }

    public record Quote(String sku, int quantity, double unitPrice,
                        int availableStock, double shipping, double total,
                        boolean degraded, long elapsedMillis) {
    }

    private record Outcome<T>(T value, boolean ok) {
    }

    public static Quote aggregate(String sku, int quantity, PriceService prices,
                                  InventoryService inventory, ShippingService shipping,
                                  Duration timeout) {
        if (sku == null || sku.isBlank()) {
            throw new IllegalArgumentException("sku não pode ser vazio");
        }
        if (quantity < 1) {
            throw new IllegalArgumentException("quantity deve ser >= 1");
        }
        if (prices == null || inventory == null || shipping == null) {
            throw new IllegalArgumentException("serviços não podem ser nulos");
        }
        if (timeout == null || timeout.toMillis() < 1) {
            throw new IllegalArgumentException("timeout deve ser >= 1 ms");
        }

        long start = System.nanoTime();
        ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor();
        try {
            CompletableFuture<Outcome<Double>> priceFuture = call(
                    () -> prices.price(sku), 0.0, timeout, executor);
            CompletableFuture<Outcome<Integer>> stockFuture = call(
                    () -> inventory.stock(sku), 0, timeout, executor);
            CompletableFuture<Outcome<Double>> shippingFuture = call(
                    () -> shipping.shipping(sku, quantity), 0.0, timeout, executor);

            CompletableFuture.allOf(priceFuture, stockFuture, shippingFuture).join();

            Outcome<Double> price = priceFuture.join();
            Outcome<Integer> stock = stockFuture.join();
            Outcome<Double> freight = shippingFuture.join();

            boolean degraded = !price.ok() || !stock.ok() || !freight.ok();
            double total = price.value() * quantity + freight.value();
            long elapsed = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start);
            return new Quote(sku, quantity, price.value(), stock.value(),
                    freight.value(), total, degraded, elapsed);
        } finally {
            executor.shutdownNow();
        }
    }

    private static <T> CompletableFuture<Outcome<T>> call(Callable<T> task, T fallback,
                                                          Duration timeout,
                                                          ExecutorService executor) {
        return CompletableFuture.supplyAsync(() -> {
                    try {
                        return new Outcome<>(task.call(), true);
                    } catch (Exception e) {
                        return new Outcome<>(fallback, false);
                    }
                }, executor)
                .orTimeout(timeout.toMillis(), TimeUnit.MILLISECONDS)
                .exceptionally(e -> new Outcome<>(fallback, false));
    }
}

