import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SolutionTest {

    private static final Solution.PriceService PRICE = sku -> 10.50;
    private static final Solution.InventoryService STOCK = sku -> 7;
    private static final Solution.ShippingService SHIPPING = (sku, qty) -> 4.25;

    @Test
    void agregaTresServicosComSucesso() {
        Solution.Quote quote = Solution.aggregate("SKU-1", 2, PRICE, STOCK, SHIPPING,
                Duration.ofSeconds(1));

        assertEquals("SKU-1", quote.sku());
        assertEquals(2, quote.quantity());
        assertEquals(10.50, quote.unitPrice(), 0.0001);
        assertEquals(7, quote.availableStock());
        assertEquals(4.25, quote.shipping(), 0.0001);
        assertEquals(25.25, quote.total(), 0.0001);
        assertFalse(quote.degraded());
        assertTrue(quote.elapsedMillis() >= 0);
    }

    @Test
    void falhaDeUmServicoUsaFallbackEMarcaDegradado() {
        Solution.PriceService failing = sku -> {
            throw new IOException("preço indisponível");
        };

        Solution.Quote quote = Solution.aggregate("SKU-1", 2, failing, STOCK, SHIPPING,
                Duration.ofSeconds(1));

        assertEquals(0.0, quote.unitPrice(), 0.0001);
        assertEquals(7, quote.availableStock());
        assertEquals(4.25, quote.shipping(), 0.0001);
        assertEquals(4.25, quote.total(), 0.0001);
        assertTrue(quote.degraded());
    }

    @Test
    void timeoutUsaFallbackSemEsperarServicoLento() {
        Solution.PriceService slow = sku -> {
            Thread.sleep(2_000);
            return 99.0;
        };

        long start = System.nanoTime();
        Solution.Quote quote = Solution.aggregate("SKU-1", 1, slow, STOCK, SHIPPING,
                Duration.ofMillis(100));
        long wall = (System.nanoTime() - start) / 1_000_000;

        assertEquals(0.0, quote.unitPrice(), 0.0001);
        assertTrue(quote.degraded());
        assertTrue(wall < 1_500, "não deveria esperar o serviço de 2s; esperou " + wall + "ms");
    }

    @Test
    void chamadasSaoConcorrentesNaoSequenciais() {
        Solution.PriceService slowPrice = sku -> {
            Thread.sleep(200);
            return 10.0;
        };
        Solution.InventoryService slowStock = sku -> {
            Thread.sleep(200);
            return 5;
        };
        Solution.ShippingService slowShipping = (sku, qty) -> {
            Thread.sleep(200);
            return 3.0;
        };

        long start = System.nanoTime();
        Solution.Quote quote = Solution.aggregate("SKU-1", 1, slowPrice, slowStock,
                slowShipping, Duration.ofSeconds(2));
        long wall = (System.nanoTime() - start) / 1_000_000;

        assertFalse(quote.degraded());
        assertTrue(wall < 500, "três chamadas de 200ms deveriam levar ~200ms; levou " + wall + "ms");
    }

    @Test
    void todosOsServicosFalhamRetornamZero() {
        Solution.PriceService p = sku -> {
            throw new IllegalStateException("p");
        };
        Solution.InventoryService i = sku -> {
            throw new IllegalStateException("i");
        };
        Solution.ShippingService s = (sku, qty) -> {
            throw new IllegalStateException("s");
        };

        Solution.Quote quote = Solution.aggregate("X", 3, p, i, s, Duration.ofMillis(200));

        assertEquals(0.0, quote.total(), 0.0001);
        assertTrue(quote.degraded());
    }

    @Test
    void servicosSaoInvocadosUmaVezPorAgregacao() {
        AtomicInteger priceCalls = new AtomicInteger();
        Solution.PriceService countingPrice = sku -> {
            priceCalls.incrementAndGet();
            return 1.0;
        };

        Solution.aggregate("A", 1, countingPrice, STOCK, SHIPPING, Duration.ofSeconds(1));
        assertEquals(1, priceCalls.get());
    }

    @Test
    void entradasInvalidasFalhamRapido() {
        assertThrows(IllegalArgumentException.class,
                () -> Solution.aggregate(null, 1, PRICE, STOCK, SHIPPING, Duration.ofSeconds(1)));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.aggregate(" ", 1, PRICE, STOCK, SHIPPING, Duration.ofSeconds(1)));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.aggregate("X", 0, PRICE, STOCK, SHIPPING, Duration.ofSeconds(1)));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.aggregate("X", 1, PRICE, STOCK, SHIPPING, Duration.ZERO));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.aggregate("X", 1, null, STOCK, SHIPPING, Duration.ofSeconds(1)));
    }
}
